import sys

def main():
    data = sys.stdin.read().split()
    m = int(data[0])
    n = int(data[1])
    b = data[2]
    pos = {c: i for i, c in enumerate(b)}
    full = (1 << m) - 1
    size = 1 << m
    cnt = [0] * size
    for tok in data[3:3 + n]:
        mask = 0
        for ch in set(tok):
            p = pos.get(ch)
            if p is not None:
                mask |= 1 << p
        cnt[mask] += 1
    nz = [a for a in range(size) if cnt[a]]
    total = 0
    for x in range(len(nz)):
        a = nz[x]
        ca = cnt[a]
        if a == full:
            total += ca * (ca - 1) // 2
        for y in range(x + 1, len(nz)):
            c = nz[y]
            if (a | c) == full:
                total += ca * cnt[c]
    print(total)

